import{_ as e,c as s,o as a,a3 as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Timesheets","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/timesheets/index.md","filePath":"master/services/timesheets/index.md","lastUpdated":1793074831000}'),r={name:"master/services/timesheets/index.md"};function n(i,t,l,h,d,g){return a(),s("div",null,t[0]||(t[0]=[o('<h1 id="timesheets" tabindex="-1">Timesheets <a class="header-anchor" href="#timesheets" aria-label="Permalink to &quot;Timesheets&quot;">​</a></h1><p>A timesheet entry records time one person spent on one task of a project. Every entry names a date, a person, a project, a task and a number of hours. Aureus adds these hours up for you, so each task shows how much time is spent, how much is left and how far along it is.</p><blockquote><p><strong>In simple words:</strong> A timesheet is a diary of who worked on what, and for how long. Aureus does the sums.</p></blockquote><p>Use timesheets when you bill by the hour or compare planned and real effort. Skip them if you only need a task list. They are optional.</p><p>Open <code>Project → Timesheets</code> from the top bar of the Project app.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Turn on <strong>Enable Timesheets</strong> and, for each project, <strong>Allow Timesheets</strong>. See <a href="./timesheet-settings.html">Timesheet settings</a>.</p></div><h2 id="how-hours-roll-up-into-a-task" tabindex="-1">How hours roll up into a task <a class="header-anchor" href="#how-hours-roll-up-into-a-task" aria-label="Permalink to &quot;How hours roll up into a task&quot;">​</a></h2><p>Each time you save or delete an entry, Aureus recalculates the task it belongs to. A sub-task is a smaller task inside a task. See <a href="./../project/task-management/sub-tasks.html">Sub tasks</a>. If the task is a sub-task, the parent task is recalculated too.</p><table tabindex="0"><thead><tr><th>Task value</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Allocated Hours</strong></td><td>The hours you plan for the task. You type this on the task.</td></tr><tr><td><strong>Time Spent</strong></td><td>Hours logged on this task only.</td></tr><tr><td><strong>Time Spent on Subtasks</strong></td><td>Hours logged on its sub tasks.</td></tr><tr><td><strong>Total Time Spent</strong></td><td><strong>Time Spent</strong> plus <strong>Time Spent on Subtasks</strong>.</td></tr><tr><td><strong>Remaining Time</strong></td><td><strong>Allocated Hours</strong> minus <strong>Total Time Spent</strong>. It can go below zero.</td></tr><tr><td><strong>Progress</strong></td><td><strong>Total Time Spent</strong> divided by <strong>Allocated Hours</strong>, as a percentage.</td></tr></tbody></table><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><p>The task <strong>Migrate CMS content</strong> in <strong>Website Revamp</strong> has 20 allocated hours. People logged 10 hours on it. Ava Lewis then logs 3 more hours with <a href="./log-time.html">Log time</a>. Its sub tasks <strong>Export legacy articles</strong> and <strong>Import and re-format media</strong> have 6 hours each.</p><ul><li><strong>Time Spent</strong> is 13 hours.</li><li><strong>Time Spent on Subtasks</strong> is 12 hours.</li><li><strong>Total Time Spent</strong> is 25 hours.</li><li><strong>Remaining Time</strong> is minus 5 hours, because the task is over its plan.</li><li><strong>Progress</strong> is 125%.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If <strong>Allocated Hours</strong> is empty or 0, <strong>Progress</strong> stays at 0. Set the hours on the task first.</p></div><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./timesheet-settings.html">Timesheet settings</a></td><td>Do this first: switches, allocated hours, summary rows and progress colours</td></tr><tr><td><a href="./log-time.html">Log time</a></td><td>Add, edit and delete entries from the Timesheets page or from a task</td></tr><tr><td><a href="./timesheet-list-and-filters.html">Timesheet list and filters</a></td><td>Columns, the total row, grouping, filters and bulk delete</td></tr></tbody></table><h2 id="suggested-order" tabindex="-1">Suggested order <a class="header-anchor" href="#suggested-order" aria-label="Permalink to &quot;Suggested order&quot;">​</a></h2><ol><li>Turn on timesheets in settings.</li><li>Allow timesheets on each project and set <strong>Allocated Hours</strong> on tasks.</li><li>Log time as people work.</li><li>Review the list and each task&#39;s progress.</li></ol><h2 id="where-timesheets-appear-in-the-project-area" tabindex="-1">Where timesheets appear in the project area <a class="header-anchor" href="#where-timesheets-appear-in-the-project-area" aria-label="Permalink to &quot;Where timesheets appear in the project area&quot;">​</a></h2><ul><li>The <strong>Timesheets</strong> tab at the bottom of the task <strong>View</strong> page. See <a href="./../project/task-management/create-task.html">Create a task</a>.</li><li>Time columns and <strong>Progress</strong> in the task list.</li><li><strong>Total Hours Spent</strong> and <strong>Top Assignees</strong> on the <a href="./../project/project-management/project-dashboard.html">project dashboard</a>.</li><li><strong>Allocated Hours</strong> and <strong>Remaining Hours</strong> on a project. See <a href="./../project/project-management/create-project.html">Create a project</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../project/task-management/sub-tasks.html">Sub tasks</a></li><li><a href="./../project/get-started/project-settings.html">Project settings</a></li><li><a href="./../../general-settings/users/manage-users.html">Manage users</a></li></ul>',21)]))}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
